import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"兰陵王·送春去","description":"","frontmatter":{"title":"兰陵王·送春去","date":"2026-11-14T00:00:00.000Z","seq":90,"categories":["美文","宋词三百首"],"collection":"《宋词三百首》","tags":["宋词三百首","宋"],"poem":true,"author":"刘辰翁","source_book":"宋词三百首"},"headers":[],"relativePath":"blogs/宋词三百首/兰陵王·送春去.md","filePath":"blogs/宋词三百首/兰陵王·送春去.md"}'),o={name:"blogs/宋词三百首/兰陵王·送春去.md"};function c(l,a,n,m,_,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="兰陵王·送春去" tabindex="-1">兰陵王·送春去 <a class="header-anchor" href="#兰陵王·送春去" aria-label="Permalink to &quot;兰陵王·送春去&quot;">​</a></h1><p class="poem-meta">宋 · 刘辰翁</p><div class="poem"><p class="poem-stanza">送春去。</p><p class="poem-stanza">春去人间无路。</p><p class="poem-stanza">秋千外、芳草连天，谁遣风沙暗南浦。</p><p class="poem-stanza">依依甚意绪。</p><p class="poem-stanza">漫忆海门飞絮。</p><p class="poem-stanza">乱鸦过，斗转城荒，不见来时试灯处。</p><p class="poem-stanza">春去。</p><p class="poem-stanza">最谁苦。</p><p class="poem-stanza">但箭雁沉边，梁燕无主。</p><p class="poem-stanza">杜鹃声里长门暮。</p><p class="poem-stanza">想玉树凋土，泪盘如露。</p><p class="poem-stanza">咸阳送客屡回顾。</p><p class="poem-stanza">斜日未能度。</p><p class="poem-stanza">春去。</p><p class="poem-stanza">尚来否。</p><p class="poem-stanza">正江令恨别，庾信愁赋。</p><p class="poem-stanza">苏堤尽日风和雨。</p><p class="poem-stanza">叹神游故国，花记前度。</p><p class="poem-stanza">人生流落，顾孺子，共夜雨。</p></div>',3)])])}const d=s(o,[["render",c]]);export{z as __pageData,d as default};
